// Which neighbourhoods have published crime data in a given month.
//
// Police forces start and stop publishing on Police.uk (e.g. Greater Manchester
// never does, Gwent paused for most of 2025-26). An LSOA counts as "has data"
// for a month only if its force published that month; otherwise it's shown
// grey and left out of the statistics, instead of looking like "zero crime".
//
// No runtime imports, so data_processing scripts running in Node can share it.

/** lsoa_forces.json, generated by data_processing/scripts/update_crime_data.mjs */
export interface LsoaForces {
    /** Force slugs, e.g. "avon-and-somerset" (as in Police.uk file names) */
    forces: string[];
    /** LSOA code → index into forces. LSOAs missing here never had a crime recorded. */
    lsoa: Record<string, number>;
}

/** crime_manifest.json, generated by data_processing/scripts/update_crime_data.mjs */
export interface CrimeManifest {
    /** Every month with a crime file, oldest first */
    months: string[];
    /** Force slugs that published street-level data, per month */
    forces_by_month: Record<string, string[]>;
}

export interface MonthCoverage {
    /** Identifies the set of reporting areas: months with equal keys cover the same LSOAs */
    key: string;
    has_data: (lsoa: string) => boolean;
}

/**
 * Build a per-month coverage lookup. Results are cached, so calling it
 * repeatedly for the same month is free.
 */
export function make_coverage(lsoa_forces: LsoaForces, manifest: CrimeManifest): (month: string) => MonthCoverage {
    const cache = new Map<string, MonthCoverage>();

    return function coverage_for(month) {
        const cached = cache.get(month);
        if (cached) {
            return cached;
        }

        const published = new Set(manifest.forces_by_month[month] ?? []);

        // Only forces that own LSOAs affect which areas count
        const key = lsoa_forces.forces.filter(force => published.has(force)).join(',');

        const has_data = (lsoa: string) => {
            const force_index = lsoa_forces.lsoa[lsoa];

            // Never had a crime recorded by any force: nothing to say it's missing, so treat as reporting zero
            if (force_index === undefined) {
                return true;
            }

            return published.has(lsoa_forces.forces[force_index]);
        };

        const coverage = { key, has_data };
        cache.set(month, coverage);
        return coverage;
    };
}
